de){grid[node.y][node.x]="path";node=node.parent;draw();await sleep(20);}return;}grid[current.y][current.x]="current";draw();await sleep(20);grid[current.y][current.x]="closed";closedSet.add(current.y+','+current.x);let neighbors=[[0,1],[1,0],[-1,0],[0,-1]];for(let [dx,dy] of neighbors){let nx=current.x+dx,ny=current.y+dy;if(nx<0||ny<0||nx>=cols||ny>=rows)continue;if(grid[ny][nx]===1)continue;if(closedSet.has(ny+','+nx))continue;let gScore=current.g+1;let existing=openSet.find(n=>n.x===nx&&n.y===ny);if(!existing||gScore<existing.g){let h=heuristic({x:nx,y:ny},goal);let node={x:nx,y:ny,g:gScore,f:gScore+h,parent:current};if(!existing)openSet.push(node);else{existing.g=gScore;existing.f=gScore+h;existing.parent=current;}}}draw();await sleep(10);}draw();}await generate();await solve();}catch(e){console.error(e);}}

